"""Маленький синтетический прайс prutki.ru (.xlsx — та же таблица, что price.xls с сайта)."""
import io

from openpyxl import Workbook

HEAD = ["Интернет-магазин заготовок prutki.ru", "Продажа в розницу и мелким оптом",
        "Электронная почта для заявок", "+7 000 000-00-00",
        "Цены и наличие от 26.10.2026 Цены в рублях за 1 (одну) заготовку. Включают НДС 22%"]
ROWS = [
    (114102, "Заготовка плита алюминиевая Д16Т 50 х 100 х 200 мм", 3290, 15),
    (114103, "Заготовка плита алюминиевая Д16Т 60 х 100 х 200 мм", 3900, 15),
    (114050, "Заготовка плита алюминиевая Д16Т 18 х 50 х 100 мм", 420, 40),
    (113001, "Заготовка лист алюминиевый Д16Т 50 х 200 х 100 мм", 3500, 5),
    (101089, "Заготовка пруток алюминиевый Д16Т 60 х 100 мм", 900, 50),
    (105001, "Заготовка круг нержавеющий 12Х18Н10Т 60 х 100 мм", 2100, 10),
    (105114, "Заготовка круг нержавеющий AISI 321 (12Х18Н10Т) 60 х 100 мм", 1900, 2),
    (122001, "Заготовка шестигранник нержавеющий AISI 304 24 х 100 мм", 700, 10),
    (130001, "Заготовка лист полиацеталевый ПОМ-С 8 х 50 х 100 мм", 150, 10),
    (131001, "Заготовка стержень фторопластовый Ф-4 10 х 50 мм", 80, 10),
    (154001, "Заготовка анод лист медный М1 10 х 50 х 100 мм", 1910, 5),  # аноды не берутся
    (None, "Раздел: прочее", None, None),  # мусорная строка
    (199999, "Заготовка лист медный М1 2 х 50 х 100 мм", 0, 0),  # без цены
]


def price_xlsx(rows=ROWS, head=HEAD, title=("Код", "Товар", "Цена ", "Остатки (шт)")) -> bytes:
    book = Workbook()
    sheet = book.active
    for line in head:
        sheet.append([line])
    sheet.append(list(title))
    for row in rows:
        sheet.append(list(row))
    out = io.BytesIO()
    book.save(out)
    return out.getvalue()
